function cross(o,a,b){ return (a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0]); }
function hull(points){
  if(points.length<3) return points.slice();
  var pts=points.slice().sort(function(p,q){ return p[1]!==q[1]? p[1]-q[1] : p[0]-q[0]; });
  var pivot=pts[0];
  var rest=pts.slice(1).sort(function(a,b){
    var ang=Math.atan2(a[1]-pivot[1],a[0]-pivot[0])-Math.atan2(b[1]-pivot[1],b[0]-pivot[0]);
    if(Math.abs(ang)>1e-12) return ang;
    var da=(a[0]-pivot[0])*(a[0]-pivot[0])+(a[1]-pivot[1])*(a[1]-pivot[1]);
    var db=(b[0]-pivot[0])*(b[0]-pivot[0])+(b[1]-pivot[1])*(b[1]-pivot[1]);
    return da-db;
  });
  var st=[pivot, rest[0]];
  for(var i=1;i<rest.length;i++){
    while(st.length>=2 && cross(st[st.length-2], st[st.length-1], rest[i])<=0) st.pop();
    st.push(rest[i]);
  }
  return st;
}
var EXPORTS={hull:hull, cross:cross};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.GrahamScanForgePure = EXPORTS; }
